/// <summary>
/// SalesLine table event handler class
/// </summary>
internal final class NDXSalesLine_tbl_EventHandler
{
}

Method.Source:
/// <summary>
/// Post Event modified field
/// </summary>
/// <param name = "_args">Argument</param>
[PostHandlerFor(tableStr(SalesLine), tableMethodStr(SalesLine, modifiedField))]
public static void SalesLine_Post_modifiedField(XppPrePostArgs _args)
{
    FieldId fieldId = _args.getArg(identifierStr(_fieldId));
    SalesLine salesLine = _args.getThis();

    boolean     ok;
    container   conErrorMessage;
    SalesQty    economicBatchSize;
    SalesQty    locSalesQtyTmp;

    switch (fieldId)
    {
        case fieldnum(SalesLine, SalesQty):
            locSalesQtyTmp = salesLine.SalesQty;

            [ok, conErrorMessage, economicBatchSize] = NDX_ItemValidity::checkValidityEconomicBatchSize(salesLine.ItemId, salesLine.SalesQty);

            if (!ok)
            {
                conErrorMessage += strfmt("@NDX:NDXSalesQuantityIncrease", economicBatchSize);   // Die Auftragsmenge wurde auf [%1] erhöht!
                salesLine.SalesQty = economicBatchSize;
                Warning(NDX_ItemValidity::conErrorMessage2ValidityMessage(conErrorMessage));
            }
            if(salesLine.SalesQty != locSalesQtyTmp)
            {
                SalesLine::modifySalesQty(salesLine,salesLine.inventDim());
            }
            break;
        case fieldnum(SalesLine, ItemId):
            NDXItemStateTable::ShowInfo(salesLine.ItemId);
            break;
    }
}
